mapper.select:
select lm.model_code as value, COALESCE(NULLIF(lm.display_name, ''), lm.model_name) as label, lm.model_code as code, 0 as disabled, json_object('modelType', lm.model_type, 'modelFamily', lm.model_family, 'status', lm.status) as meta from kb_logical_models lm where 1 = 1 and lm.is_deleted = 0 and lm.status = 'ENABLED' and lm.model_family = #{modelFamilyCode}
and (lm.model_name like concat('%', #{keyword}, '%') or lm.model_code like concat('%', #{keyword}, '%') or lm.display_name like concat('%', #{keyword}, '%'))
order by lm.sort_order asc, lm.id asc

select m.model_code as value, COALESCE(lm.model_name, m.model_code) as label, m.model_code as code, 0 as disabled, json_object('providerName', COALESCE(p.name, m.provider_account_code), 'providerAccountCode', m.provider_account_code, 'modelName', lm.model_name, 'name', lm.model_name, 'modelType', lm.model_type, 'logicalModelCode', pmm.logical_model_code, 'status', m.status) as meta from kb_models m left join kb_provider_model_mappings pmm on pmm.model_id = m.id left join kb_logical_models lm on lm.model_code = pmm.logical_model_code and lm.is_deleted = 0 left join kb_providers p on p.code = m.provider_account_code where 1 = 1 and m.status = 'ENABLED' and pmm.logical_model_code = #{logicalModelCode} and lm.model_family = #{modelFamilyCode} and m.provider_account_code = #{providerAccountCode}
and (m.model_code like concat('%', #{keyword}, '%') or m.upstream_model like concat('%', #{keyword}, '%') or lm.model_name like concat('%', #{keyword}, '%'))
order by m.model_code asc

select mp.pool_code as value, mp.name as label, mp.pool_code as code, 0 as disabled from kb_model_pools mp where 1 = 1 and mp.is_deleted = 0 and mp.status = 'ENABLED' and mp.logical_model_code = #{logicalModelCode}
and (mp.name like concat('%', #{keyword}, '%') or mp.pool_code like concat('%', #{keyword}, '%'))
order by mp.id desc

select br.code as value, br.code as label, br.code as code, 0 as disabled from kb_billing_rules br where br.status <> 'DELETED' and br.status = 'ACTIVE' and br.model_family = #{modelFamilyCode}
and br.code like concat('%', #{keyword}, '%')
order by br.code asc
